import { Prism, languages, insertBefore } from '../prismCore'
import './javascript'
import './javadoclike'
import './typescript'

var javascript = languages.js;

var type = /\{(?:[^{}]|\{(?:[^{}]|\{[^{}]*\})*\})+\}/.source;
var parameterPrefix = `(@(?:arg|argument|param|property)\\s+(?:${type}\\s+)?)`;

languages.jsdoc = languages.extend('javadoclike', {
	'parameter': {
		// @param {string} foo - foo bar
		pattern: RegExp(parameterPrefix + /(?:(?!\s)[$\w\xA0-\uFFFF.])+(?=\s|$)/.source),
		lookbehind: true,
		inside: {
			'punctuation': /\./
		}
	}
});

insertBefore('jsdoc', 'keyword', {
	'optional-parameter': {
		// @param {string} [baz.foo="bar"] foo bar
		pattern: RegExp(parameterPrefix + /\[(?:(?!\s)[$\w\xA0-\uFFFF.])+(?:=[^[\]]+)?\](?!\S)/.source),
		lookbehind: true,
		inside: {
			'code': {
				pattern: /(=)[\s\S]+(?=.)/,
				lookbehind: true,
				inside: javascript,
				alias: 'language-javascript'
			},
			'punctuation': /[=[\]]/,
			'parameter': {
				pattern: /[\s\S]+/,
				inside: {
					'punctuation': /\./
				}
			},
		}
	},
	'class-name': [
		{
			pattern: RegExp(/(@(?:augments|class|extends|interface|memberof!?|template|this|typedef)\s+(?:<TYPE>\s+)?)[A-Z]\w*(?:\.[A-Z]\w*)*/.source.replace(/<TYPE>/g, type)),
			lookbehind: true,
			inside: {
				'punctuation': /\./
			}
		},
		{
			pattern: RegExp('(@[a-z]+\\s+)' + type),
			lookbehind: true,
			inside: {
				'string': javascript.string,
				'number': javascript.number,
				'boolean': javascript.boolean,
				'keyword': languages.ts.keyword,
				'operator': /=>|\.\.\.|[&|?:*]/,
				'punctuation': /[.,;=<>{}()[\]]/
			}
		}
	],
	'example': {
		pattern: /(@example\s+(?!\s))(?:[^@\s]|\s+(?!\s))+?(?=\s*(?:\*\s*)?(?:@\w|\*\/))/,
		lookbehind: true,
		inside: {
			'code': {
				pattern: /^([\t ]*(?:\*\s*)?)\S.*$/m,
				lookbehind: true,
				inside: javascript,
				alias: 'language-javascript'
			}
		}
	}
});

languages.javadoclike.addSupport('javascript', languages.jsdoc);
